<style scoped lang="scss" src="./logo.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import { LogoAlignValues } from "./logo.constants";

@Component
export default class Logo extends Vue {
  @Prop({ type: String }) source;
  @Prop({ type: Number }) maxHeight;
  @Prop({ type: Number }) maxWidth;
  @Prop({ type: String, validator: has(LogoAlignValues) }) align;

  get style() {
    return {
      flex: `0 1 auto`,
      maxHeight: `${this.maxHeight}px`,
      maxWidth: `${this.maxWidth}px`,
    };
  }
}
</script>

<template>
  <div class="Logo" :style="style">
    <img :src="source" :style="style" />
  </div>
</template>
